// Per-giveaway settings — edit these values between runs, then Execute.
// GUI dry-run calls pass {runId, followersUrl?, runLabel?} via GUI Input.
// Remote n8n (Coolify VPS) uses http://browser:5679 (same Compose network).
// Local-dev collector: see scripts/fb-followers-collector/README.md and set
// the collector URL to the tunneled address.
// There is no separate pre-flight status call anymore — Collect Followers
// via Browser does its own single-navigation auth check and returns a clean
// authenticated:false + AUTH_REQUIRED error on its own, so a second HTTP
// call (and the extra open/close browser-tab cycle it caused) is unnecessary.
// Every run stores its full result to the giveaway_runs Data Table — visible
// and downloadable from the Control Panel GUI (live activity log, results,
// JSON download). No external Sheets or Telegram integration.
const incoming = $input.first().json || {};
return [{
  json: {
    followersUrl: incoming.followersUrl || 'https://www.facebook.com/profile.php?id=61579485972085&sk=followers',
    collectorCollectUrl: 'http://browser:5679/collect',
    scrollDelayMs: 2500,
    postScrollWaitMs: 2500,
    emptyScrollThreshold: 10,
    maxScrollAttempts: 500,
    runLabel: incoming.runLabel || 'giveaway',
    runId: incoming.runId || ('run-' + Date.now())
  }
}];

const collected = $('Collect Followers via Browser').first().json;
const cfg = $('Giveaway Config').first().json;
const profiles = collected.profiles || [];
const stats = collected.stats || {};
const runLabel = cfg.runLabel || 'giveaway';
const extractedAt = new Date().toISOString();
function normUrl(u) {
  const s = String(u || '').trim();
  if (!s) return '';
  let v = s.split('#')[0];
  const q = v.indexOf('?');
  if (q >= 0) {
    const base = v.slice(0, q);
    const query = v.slice(q + 1);
    const idm = query.match(/(^|&)id=(\d+)/i);
    v = idm ? base + '?id=' + idm[2] : base;
  }
  v = v.replace(/\/+$/, '');
  return v.toLowerCase();
}
function profileId(u) {
  const s = String(u || '').trim();
  if (!s) return '';
  const idm = s.match(/[?&]id=(\d+)/i);
  if (idm) return 'id:' + idm[1];
  const clean = s.split('?')[0].split('#')[0].replace(/\/+$/, '');
  const parts = clean.split('/').filter(function (p) { return p; });
  return parts.length ? parts[parts.length - 1].toLowerCase() : '';
}
function fbHost(u) {
  const m = String(u || '').trim().match(/^https?:\/\/([^/:?#]+)/i);
  if (!m) return '';
  return m[1].toLowerCase();
}
function validId(u) {
  const s = String(u || '').trim();
  if (!s) return false;
  const h = fbHost(s);
  if (h !== 'facebook.com' && !h.endsWith('.facebook.com') && h !== 'fb.com' && !h.endsWith('.fb.com')) return false;
  return profileId(s) !== '';
}
// Facebook renders each follower row as TWO separate <a> elements sharing
// the same profile URL: one wraps only the avatar image (no visible text),
// one wraps the name. The collector emits every raw sighting as-is (needed
// for the audit trail), so the same URL legitimately appears once with a
// blank name and once with the real name. "First sighting wins" dedupe
// always picked the blank one, since the avatar anchor renders first in DOM
// order — confirmed live: 96 of 192 raw rows had real names, but
// finalRouletteCount was 0 every time. Fix: prefer whichever sighting of a
// key actually has a name, not just the first one encountered. Plain
// Object.create(null) maps avoid any prototype-property key collision
// (independent review note); an empty normalized key (never expected in
// practice, since validId already requires a facebook.com host + id, which
// normUrl always preserves, but kept as an explicit invariant rather than
// assumed) falls back to the OLD permissive per-item behavior instead of
// being force-marked a duplicate, so this can only improve eligibility
// versus the old logic, never regress it (independent review finding).
const nameByKey = Object.create(null);
for (const p of profiles) {
  const url = p && (p.profileUrl || p.url) ? String(p.profileUrl || p.url).trim() : '';
  const key = normUrl(url);
  const name = p && p.displayName ? String(p.displayName).trim() : '';
  if (key && name && !nameByKey[key]) nameByKey[key] = name;
}
const seenCanonical = Object.create(null);
let duplicates = 0;
let missingNames = 0;
let invalidIds = 0;
// rawRows keeps only the canonical (non-duplicate) sighting per follower —
// every raw DOM sighting used to go in here (76,930 rows for a ~931-person
// page, one avatar-anchor row plus one name-anchor row per follower plus
// re-sightings across scroll passes), which is impractical to write to the
// Raw Followers Sheet. The full per-sighting detail was only ever useful
// for debugging the dedupe logic itself, not for the audit trail. The
// isDuplicate column is kept (always 'no' now) so the sheet schema/any
// existing header stays stable rather than silently losing a column.
const rawRows = [];
const rouletteRows = [];
for (const p of profiles) {
  const name = p && p.displayName ? String(p.displayName).trim() : '';
  const url = p && (p.profileUrl || p.url) ? String(p.profileUrl || p.url).trim() : '';
  const key = normUrl(url);
  const id = profileId(url);
  const okUrl = validId(url);
  if (!name) missingNames++;
  if (!okUrl) invalidIds++;
  let isDup = false;
  if (key !== '') {
    const bestName = nameByKey[key] || '';
    const isCanonical = !seenCanonical[key] && (bestName === '' || name === bestName);
    if (isCanonical) seenCanonical[key] = true;
    isDup = !isCanonical;
  }
  if (isDup) duplicates++;
  let status = 'valid';
  if (!okUrl) { status = 'invalid-id'; } else if (isDup) { status = name ? 'duplicate' : 'missing-name'; } else if (!name) { status = 'missing-name'; }
  if (!isDup) { rawRows.push({ displayName: name, profileUrl: url, profileId: id, extractedAt: extractedAt, isDuplicate: 'no', validationStatus: status, runLabel: runLabel }); }
  if (!isDup && okUrl && name) { rouletteRows.push({ displayName: name, profileUrl: url, profileId: id, runLabel: runLabel }); }
}
const ok = collected.ok === true;
const stopReason = stats.stopReason || 'unknown';
const isComplete = ok && stopReason === 'empty-threshold-reached';
return [{ json: { isComplete: isComplete, collectorOk: ok, collectorError: collected.error || '', authenticated: collected.authenticated !== false, stopReason: stopReason, scrollAttempts: stats.scrollAttempts || 0, totalEncountered: stats.totalEncountered || profiles.length, uniqueFollowers: Object.keys(seenCanonical).length, duplicatesRemoved: duplicates, missingNames: missingNames, invalidIds: invalidIds, finalRouletteCount: rouletteRows.length, readyForDraw: isComplete && rouletteRows.length > 0, rawRows: rawRows, rouletteRows: rouletteRows, runLabel: runLabel } }];

const v = $('Validate Dedupe and Build Rows').first().json;
const cfg = $('Giveaway Config').first().json;
const summary = { runId: cfg.runId, runLabel: v.runLabel, totalEncountered: v.totalEncountered, uniqueFollowers: v.uniqueFollowers, duplicatesRemoved: v.duplicatesRemoved, missingNames: v.missingNames, invalidIds: v.invalidIds, finalRouletteCount: v.finalRouletteCount, scrollAttempts: v.scrollAttempts, stopReason: v.stopReason, readyForDraw: v.readyForDraw };
return [{ json: { runId: cfg.runId, runLabel: v.runLabel, status: 'complete', summaryJson: JSON.stringify(summary), rawRowsJson: JSON.stringify(v.rawRows || []), rouletteRowsJson: JSON.stringify(v.rouletteRows || []) } }];
